# HOLMES: Bayesian logistic regression (DNA data, disease risk)
# min sum_{i=1}^{M} log(1 + exp(-v_i)) + 0.5*lambda*sum_j theta_j^2
# v_i = sum_j A_ij * theta_j, M=1859 data points, N=180 variables
# LAMBDA=0.0 (no regularization), theta_j >= 0 (SIF default bounds)
# ILOGIT group type: F(v) = log(1 + exp(-v))
# Source: Chris Holmes (Oxford), Bayesian model for genetic associations

function _holmes_ilogit(v::T) where {T <: Real}
    log(one(T) + exp(-v))
end

function _dholmes_ilogit(v::T) where {T <: Real}
    e = exp(-v)
    -e / (one(T) + e)
end

function _d2holmes_ilogit(v::T) where {T <: Real}
    e = exp(-v)
    e / (one(T) + e)^2
end

ExaModels.@register_univariate(_holmes_ilogit, _dholmes_ilogit, _d2holmes_ilogit)

